const timeout = 3000;
const url = 'https://www.signgate.com';

function getAuthCode(options) {
  const path = '/web-relay/cert/sid.sg';
  return new Promise((resolve, reject) => {
    secukit.config.jqueryAlias.ajax({
      url: options.url ? `${options.url}${path}` : `${url}${path}`,
      dataType: 'text',
      method: 'POST',
      timeout: timeout,
      data: ``,
    })
      .done(function (res) {
        res = getParameterMap(res);
        if (res.resultCode !== '2000') {
          reject(res);
          return;
        }

        resolve(res);
      })
      .fail(function (err) {
        reject({resultCode: "NETWORK ERROR", message: "네트워크 오류가 발생했습니다. 관리자에게 문의하세요."});
      });
  });
}

function getCert(authCode, options) {
  const path = '/web-relay/cert/cert_dn.sg';
  return new Promise((resolve, reject) => {
    secukit.config.jqueryAlias.ajax({
      url: options.url ? `${options.url}${path}` : `${url}${path}`,
      dataType: 'text',
      method: 'POST',
      timeout: timeout,
      data: `authcode=${encodeURIComponent(authCode)}`,
    })
      .done(function (res) {
        res = getParameterMap(res);
        if (res.resultCode !== '2000') {
          reject(res);
          return;
        }

        resolve(res);
      })
      .fail(function (err) {
        reject({resultCode: "NETWORK ERROR", message: "네트워크 오류가 발생했습니다. 관리자에게 문의하세요."});
      });
  });
}

function setCert(authCode, pkcs12, signature, certificate, options) {
  const path = '/web-relay/cert/cert_up.sg';
  return new Promise((resolve, reject) => {
    secukit.config.jqueryAlias.ajax({
      url: options.url ? `${options.url}${path}` : `${url}${path}`,
      crossDomain: true,
      async: false,
      dataType: 'text',
      method: 'POST',
      timeout: timeout,
      xhrFields: {
        withCredentials: false,
      },
      data:
        'authcode=' +
        encodeURIComponent(authCode) +
        '&pkcs12=' +
        encodeURIComponent(pkcs12) +
        '&signature=' +
        encodeURIComponent(signature) +
        '&certificate=' +
        encodeURIComponent(removePEMHeader(removeCRLF(certificate))),
    })
      .done(function (res) {
        res = getParameterMap(res);
        if (res.resultCode !== '2000') {
          reject(res);
          return;
        }

        resolve(res);
      })
      .fail(function (err) {
        reject({resultCode: "NETWORK ERROR", message: "네트워크 오류가 발생했습니다. 관리자에게 문의하세요."});
      });
  });
}

function getParameterMap(message) {
  var parameters = new Object();
  var pattern = new RegExp('(\\w+)=([^}]*)', 'mg');
  var matchArray;
  while ((matchArray = pattern.exec(message)) != null) {
    parameters[matchArray[1]] = matchArray[2];
  }

  return parameters;
}

function removeCRLF(str) {
  var i = 0;
  var buf = "";
  for (i = 0; i < str.length; i++) {
      if (str.charAt(i) !== '\n' && str.charAt(i) !== '\r') {
          buf += str.charAt(i);
      }
  }
  return buf;
}

function removePEMHeader(str) {
  var startStr = "-----BEGIN CERTIFICATE-----";
  var endStr = "-----END CERTIFICATE-----";
  var startP7 = "-----BEGIN PKCS7-----";
  var endP7 = "-----END PKCS7-----";
  var resultStr1 = str.replace(startStr, "");
  var resultStr2 = resultStr1.replace(endStr, "");
  var resultStr3 = resultStr2.replace(startP7, "");
  var resultStr4 = resultStr3.replace(endP7, "");

  return resultStr4;
}


export default {
  getAuthCode,
  getCert,
  setCert,
};
