// secukit.config.debug 설정에 따라 로그 출력 여부를 결정하도록 설정
export default {
  info: function (...args) {
    if (!secukit.config.debug) return;
    console.log(...args);
  },

  error: function (...args) {
    if (!secukit.config.debug) return;
    console.error(...args);
  },

  warn: function (args) {
    if (!secukit.config.debug) return;
    console.warn(...args);
  },
};
