import api from './api';
import nxsApi from '../method/cert/nxs/api';
import { triggerFocus } from '../common/utils';
setEventHandler();

function setEventHandler() {
  secukit.config.jqueryAlias('#secukit-close-relay-import').on('click', function () {
    secukit.config.jqueryAlias('#secukit-relay-import, .secukit-relay-fence, .secukit-relay').addClass('secukit-d-none');
  });

  setExportEventHandler();
  setCertEventHandler();
  setCertPopupEventHandler();
}

function setExportEventHandler() {
  secukit.config.jqueryAlias('#secukit-close-relay-export').on('click', function () {
    secukit.config.jqueryAlias('#secukit-relay-export, .secukit-relay-fence, .secukit-relay').addClass('secukit-d-none');
  });

  secukit.config.jqueryAlias('.secukit-auth-number-input').on('keyup', (e) => {
    e.currentTarget.value = e.currentTarget.value.replace(/[^0-9]/g, '');
    let keycode = e.key || e.which || e.charCode || e.keyCode;
    // backspace
    if (keycode === 8 || keycode === 'Backspace') {
      if (e.currentTarget.value.length !== 0) return;
      if (e.currentTarget.id === 'export-auth-number3') triggerFocus(secukit.config.jqueryAlias('#export-auth-number2'));
      else if (e.currentTarget.id === 'export-auth-number2') triggerFocus(secukit.config.jqueryAlias('#export-auth-number1'));
    } else {
      if (e.currentTarget.value.length !== 4) return;
      if (e.currentTarget.id === 'export-auth-number1') triggerFocus(secukit.config.jqueryAlias('#export-auth-number2'));
      else if (e.currentTarget.id === 'export-auth-number2') triggerFocus(secukit.config.jqueryAlias('#export-auth-number3'));
    }
  });

  secukit.config.jqueryAlias('#export-auth-number3').on('keyup', (e) => {
    let keycode = e.key || e.which || e.charCode || e.keyCode;
    if (keycode === 'Enter' || keycode === 13) {
      secukit.config.jqueryAlias('#secukit-relay-export-confirm').trigger('click');
    }
  });
}

function setCertEventHandler() {
  secukit.config.jqueryAlias('#secukit-close-relay-cert').on('click', function () {
    secukit.config.jqueryAlias('.secukit-relay-cert-wrapper, .secukit-relay-fence, .secukit-relay').addClass('secukit-d-none');
  });
  secukit.config.jqueryAlias(document).on('click', '.secukit-relay-cert-media:not(.secukit-not-installed)', function (e) {
    secukit.config.jqueryAlias('.secukit-relay-cert-media').removeClass('secukit-active');
    secukit.config.jqueryAlias(this).addClass('secukit-active');

    let type = secukit.config.jqueryAlias(this).data('type');
    if (type === 'USB') {
      nxsApi
        .selectStorage(type, 'NULL')
        .then((res) => {
          openMediaListPopup(res.reply);
        })
        .catch((err) => {
          if (err === 'timeout') secukit.dialog.alert.error('Connection Timeout', '프로그램이 이미 실행 중인지 확인해주세요.');
        });
    }
  });
}

function setCertPopupEventHandler() {
  secukit.config.jqueryAlias('#secukit-close-relay-cert-media-popup').on('click', function () {
    secukit.config.jqueryAlias('.secukit-relay-cert-media-popup-fence, .secukit-relay-cert-media-popup').addClass('secukit-d-none');
  });

  secukit.config.jqueryAlias(document).on('click', '.secukit-relay-cert-media-popup-content-list__item', function (e) {
    secukit.config.jqueryAlias('.secukit-relay-cert-media-popup-content-list__item').removeClass('secukit-active');
    secukit.config.jqueryAlias('.secukit-relay-cert-media-popup-content-list__item').prop('title', '선택되지 않음');
    secukit.config.jqueryAlias(this).prop('title', '선택됨');
    secukit.config.jqueryAlias(this).addClass('secukit-active');
  });

  secukit.config.jqueryAlias(document).on('keyup', '.secukit-relay-cert-media-popup-content-list__item', function (e) {
    let keycode = e.key || e.which || e.charCode || e.keyCode;
    if (keycode === 'Enter' || keycode === 13) {
      secukit.config.jqueryAlias('#secukit-relay-cert-popup-confirm').trigger('click');
    }
  });

  secukit.config.jqueryAlias('#secukit-relay-cert-popup-confirm').on('click', function () {
    let extraValue = secukit.config.jqueryAlias('.secukit-relay-cert-media-popup-content-list__item.secukit-active').data('extra-value');
    secukit.config.jqueryAlias('#secukit-relay-cert-media-usb>.secukit-relay-cert-media__name').html(`이동식디스크(${extraValue.diskName})`);
    secukit.config.jqueryAlias('#secukit-relay-cert-media-usb').data('extra-value', extraValue);

    secukit.config.jqueryAlias('#secukit-close-relay-cert-media-popup').trigger('click');
  });
}

function openAuthNumberExport(pkcs12, signature, certificate, options) {
  secukit.config.jqueryAlias('.secukit-auth-number-input').val('');

  secukit.config.jqueryAlias('#secukit-relay-export-confirm').off('click');
  secukit.config.jqueryAlias('#secukit-relay-export-confirm').on('click', function () {
    let authCode = secukit.config.jqueryAlias('#export-auth-number1').val() + secukit.config.jqueryAlias('#export-auth-number2').val() + secukit.config.jqueryAlias('#export-auth-number3').val();
    if (authCode.length !== 12) {
      secukit.dialog.alert.warn('인증번호 미입력', '인증번호 12자리를 입력해주세요.', {
        onclose: function () {
          triggerFocus(secukit.config.jqueryAlias('#export-auth-number1'));
        },
      });
      return;
    }

    api
      .setCert(authCode, pkcs12, signature, certificate, options)
      .then(function (res) {
        secukit.dialog.alert.success('인증서 내보내기', '인증서를 성공적으로 내보냈습니다.', {
          onclose: () => {
            secukit.config.jqueryAlias('#secukit-close-relay-export').trigger('click');
          },
        });
      })
      .catch(function (err) {
        secukit.dialog.alert.error(err.resultCode, err.message);
      });
  });

  secukit.config.jqueryAlias('#secukit-relay-export, .secukit-relay-fence, .secukit-relay').removeClass('secukit-d-none');
  triggerFocus(secukit.config.jqueryAlias('#export-auth-number1'));
}

function openAuthNumberImport(options) {
  api
    .getAuthCode(options)
    .then(function (res) {
      console.log(res);
      let authCode = res.authcode;
      secukit.config.jqueryAlias('#import-auth-number1').val(authCode.substring(0, 4));
      secukit.config.jqueryAlias('#import-auth-number2').val(authCode.substring(4, 8));
      secukit.config.jqueryAlias('#import-auth-number3').val(authCode.substring(8));

      secukit.config.jqueryAlias('#secukit-relay-import-confirm').off('click');
      secukit.config.jqueryAlias('#secukit-relay-import-confirm').on('click', function () {
        api
          .getCert(authCode, options)
          .then(function (res) {
            openSelectCertMedia(res.pkcs12);
            secukit.config.jqueryAlias('#secukit-relay-import').addClass('secukit-d-none');
          })
          .catch(function (err) {
            secukit.dialog.alert.error(err.resultCode, err.message);
          });
      });

      secukit.config.jqueryAlias('#secukit-relay-import, .secukit-relay-fence, .secukit-relay').removeClass('secukit-d-none');
      triggerFocus(secukit.config.jqueryAlias('#secukit-relay-import-confirm'));
    })
    .catch(function (err) {
      console.log(err);
    });
}

function openSelectCertMedia(pkcs12) {
  secukit.config.jqueryAlias('#secukit-relay-cert-password').val("");
  secukit.config.jqueryAlias('.secukit-relay-cert-media').first().trigger('click');
  
  secukit.config.jqueryAlias('#secukit-relay-cert-confirm').off('click');
  secukit.config.jqueryAlias('#secukit-relay-cert-confirm').on('click', function () {
    let password = secukit.config.jqueryAlias('#secukit-relay-cert-password').val();

    if (!password) {
      secukit.dialog.alert.warn('인증서 비밀번호 미입력', '인증서 비밀번호를 입력해주세요.', {
        onclose: function () {
          triggerFocus(secukit.config.jqueryAlias('#secukit-relay-cert-password'));
        },
      });
      return;
    }

    let mediaType = secukit.config.jqueryAlias('.secukit-relay-cert-media.secukit-active').data('type');
    let extraValue = secukit.config.jqueryAlias('.secukit-relay-cert-media.secukit-active').data('extra-value');
    extraValue = extraValue ? extraValue.diskName : 'NULL';

    secukit.api.importP12FromData(pkcs12, password, mediaType, extraValue, function (res, err) {
      if (err !== undefined) {
        secukit.dialog.alert.error(err.code, err.message);
        return;
      }

      secukit.dialog.alert.success('인증서 가져오기', '인증서를 성공적으로 가져왔습니다.', {
        onclose: () => {
          secukit.config.jqueryAlias('#secukit-close-relay-cert').trigger('click');
        },
      });
    });
  });

  secukit.config.jqueryAlias('.secukit-relay-cert-wrapper').removeClass('secukit-d-none');
}

function openMediaListPopup(data) {
  secukit.config.jqueryAlias('.secukit-relay-cert-media-popup-content-list').html('');
  for (let i = 1; i <= data.size; i++) {
    secukit.config.jqueryAlias(`<button class='secukit-relay-cert-media-popup-content-list__item'>
        ${data[i].diskName} 
      </button>`)
      .data('extra-value', data[i])
      .appendTo('.secukit-relay-cert-media-popup-content-list');
  }

  secukit.config.jqueryAlias('.secukit-relay-cert-media-popup-content-list__item').first().trigger('click');
  secukit.config.jqueryAlias('.secukit-relay-cert-media-popup-fence, .secukit-relay-cert-media-popup').removeClass('secukit-d-none');
  triggerFocus(secukit.config.jqueryAlias('.secukit-relay-cert-media-popup-content-list__item').first());
}

export default {
  openAuthNumberExport,
  openAuthNumberImport,
};
