const url = `${location.protocol}//127.0.0.1:${location.protocol === 'https:' ? '14315' : '14319'}/?TOKEN=SecuKitOne&serviceType=1`;
function _getTimeout(fname, args) {
  if (!args.mediaType) return 10000;

  if ((fname === 'selectStorage' || fname === 'selectCertificate') && (args.mediaType === 'BIOHSM' || args.mediaType === 'HSM' || args.mediaType === 'PHONE')) return 0;
  else return 10000;
}

function call(fname, args) {  
  return new Promise((resolve, reject) => {
    secukit.config.jqueryAlias.ajax({
      url: url,
      type: 'post',
      method: 'post',
      // timeout: _getTimeout(fname, args),
      data: JSON.stringify({
        callback: '',
        exfunc: {
          fname: fname,
          args: [args],
        },
      }),
    })
      .done(function (data) {
        resolve(JSON.parse(data));
      })
      .fail(function (request, status) {
        reject(status);
      });
  });
}

export { call };
