import './create';
import api from './api';
import dialog from './dialog';

window.secukit = window.secukit || {};
  
secukit.config.jqueryAlias('.secukit-relay')[0].style.setProperty('--main-color', secukit.config.theme.mainColor);
secukit.config.jqueryAlias('.secukit-relay')[0].style.setProperty('--text-placeholder-color', secukit.config.theme.textPlaceholderColor);
secukit.config.jqueryAlias('.secukit-relay')[0].style.setProperty('--text-color', secukit.config.theme.textColor);
secukit.config.jqueryAlias('.secukit-relay')[0].style.setProperty('--focus-shadow-color', secukit.config.theme.focusShadowColor);
secukit.config.jqueryAlias('.secukit-relay')[0].style.setProperty('--border-color', secukit.config.theme.borderColor);
secukit.config.jqueryAlias('.secukit-relay')[0].style.setProperty('--sidebar-bg-color', secukit.config.theme.sidebarBgColor);
secukit.config.jqueryAlias('.secukit-relay')[0].style.setProperty('--sidebar-item-color', secukit.config.theme.sidebarItemColor);
secukit.config.jqueryAlias('.secukit-relay')[0].style.setProperty('--button-color', secukit.config.theme.buttonColor);
secukit.config.jqueryAlias('.secukit-relay')[0].style.setProperty('--button-bg-color', secukit.config.theme.buttonBgColor);

secukit.relay = {
  import: function (options) {
    options = options || {};
    dialog.openAuthNumberImport(options);
  },

  export: function (options) {
    options = options || {};

    secukit.setSingleMode();
    secukit.dialog.open();
    secukit.api.exportP12ToData(function (res, err) {
      if (err !== undefined) {
        secukit.dialog.alert.error(err.code, err.message);
        return;
      }
      secukit.dialog.close();

      let pkcs12 = res.exportP12toData;
      let signature = res.signature;     

      secukit.api.getCertInfoIssue(function (res, err) {
        if (err !== undefined) {
          secukit.dialog.alert.error(err.code, err.message);
          return;
        }

        let certificate = res.certPEM;
        dialog.openAuthNumberExport(pkcs12, signature, certificate, options);
      });      
    });
  },
};
