/**
 * 파일 다운로드 객체를 생성하는 내부 함수
 * @param {string} url 다운로드할 파일 경로 (파일 이름 포함)
 * @param {string} fileName 다운로드 파일의 이름 지정
 */
function _createDownloadElement(url, fileName) {
  let a = document.createElement('a');
  a.style.display = 'none';
  a.href = url;
  a.download = fileName;
  document.body.appendChild(a);
  return a;
}

/**
 * 파일 다운로드
 * @param {string} url 다운로드할 파일 경로 (파일 이름 포함)
 * @param {string} fileName 다운로드 파일의 이름 지정
 */
function download(url, fileName) {
  let a = _createDownloadElement(url, fileName);
  a.click();
  window.URL.revokeObjectURL(url);
  document.body.removeChild(a);
}

/**
 * Blob 데이터 다운로드
 * @param {string} blob blob 데이터
 * @param {string} fileName 다운로드 파일의 이름 지정
 */
function downloadPFX(blob, fileName) {
  // Internet Explorer의 경우 Blob 데이터 접근 시 액세스 거부 오류 발생
  // window.URL.createObjectURL 대신 navigator.msSaveOrOpenBlob API 이용
  if (getBrowser() === 'ie') {
    navigator.msSaveOrOpenBlob(blob, fileName);
    return;
  }

  switch (getOS()) {
    case 'ios':
      let reader = new FileReader(); // iOS에서는 File Reader를 이용
      reader.onload = (e) => {
        let a = _createDownloadElement(reader.result, fileName);
        a.setAttribute('target', '_blank');
        a.click();

        setTimeout(() => {
          document.body.removeChild(a);
        }, 100);
      };
      reader.readAsDataURL(blob);
      break;
    default:
      let a = _createDownloadElement(window.URL.createObjectURL(blob), fileName);
      a.click();

      setTimeout(() => {
        window.URL.revokeObjectURL(a.href);
        document.body.removeChild(a);
      }, 100);

      break;
  }
}
/**
 * OS 구분 값 가져오기 (버전 정보는 미포함)
 * @returns "Mac OS", "iOS", "Windows", "Android", "Linux"
 */
function getOS() {
  let userAgent = window.navigator.userAgent,
    platform = window.navigator.platform,
    macosPlatforms = ['Macintosh', 'MacIntel', 'MacPPC', 'Mac68K'],
    windowsPlatforms = ['Win32', 'Win64', 'Windows', 'WinCE'],
    iosPlatforms = ['iPhone', 'iPad', 'iPod'],
    os = null;

  if (macosPlatforms.indexOf(platform) !== -1) {
    os = 'macOS';
  } else if (iosPlatforms.indexOf(platform) !== -1) {
    os = 'iOS';
  } else if (windowsPlatforms.indexOf(platform) !== -1) {
    os = 'Windows';
  } else if (/Android/.test(userAgent)) {
    os = 'Android';
  } else if (!os && /Linux/.test(platform)) {
    os = 'Linux';
  }

  return os;
}
/**
 * 브라우저 구분 값 가져오기
 * @returns "opera", "chrome", "safari", "firefox", "ie"
 */
function getBrowser() {
  let browser;
  if ((navigator.userAgent.indexOf('Opera') || navigator.userAgent.indexOf('OPR')) != -1) browser = 'opera';
  else if (navigator.userAgent.indexOf('Chrome') != -1) browser = 'chrome';
  else if (navigator.userAgent.indexOf('Safari') != -1) browser = 'safari';
  else if (navigator.userAgent.indexOf('Firefox') != -1) browser = 'firefox';
  else if (navigator.userAgent.indexOf('MSIE') != -1 || !!document.documentMode == true) browser = 'ie';
  else browser = 'unknown';

  return browser;
}

/**
 * 라이선스 및 모듈 설정을 교차로 파악하여 간편인증 사용 여부 확인
 * @returns {boolean}
 */
function isUsePro() {
  if (!secukit.context.license.method) return false;

  return (
    secukit.config.methodOrder.some((method) => {
      return ['samsung-pass', 'wooribank', 'payco', 'naver', 'pass', 'kakao'].includes(method);
    }) && secukit.context.license.method.includes('pro')
  );
}

/**
 * 라이선스 및 모듈 설정을 교차로 파악하여 인증서 모듈 사용 여부 확인
 * @returns {boolean}
 */
function isUseCert() {
  if (!secukit.context.license.method) return false;

  let licenseChecked = secukit.context.license.method.includes('browser') || secukit.context.license.method.includes('nxs');

  return secukit.config.methodOrder.includes('cert') && licenseChecked;
}

/**
 * 라이선스 및 모듈 설정을 교차로 파악하여 클라우드 사용 여부 확인
 * @returns {boolean}
 */
function isUseCloud() {
  if (!secukit.context.license.method) return false;

  return secukit.context.license.method.includes('cloud');
}
/**
 * 라이선스 및 모듈 설정을 교차로 파악하여 모바일 ID 사용 여부 확인
 * @returns {boolean}
 */
function isUseMobileId() {
  if (!secukit.context.license.method) return false;

  return secukit.context.license.method.includes('mobile-id');
}
/**
 * iOS 버전 정보 가져오기
 * @returns ios 버전 정보
 */
function getiOSVersion() {
  return parseInt(navigator.appVersion.match(/OS (\d+)_(\d+)_?(\d+)?/)[1], 10);
}
/**
 * Android 버전 정보 가져오기
 * @returns Android 버전 정보
 */
function getAndroidVersion(ua) {
  ua = (ua || navigator.userAgent).toLowerCase();
  let match = ua.match(/android\s([0-9\.]*)/i);
  return parseInt(match[1], 10);
}
/**
 * 태블릿인지 아닌지 여부
 * @returns {boolean}
 */
function isTablet() {
  let userAgent = navigator.userAgent.toLowerCase();
  return /(ipad|tablet|(android(?!.*mobile))|(windows(?!.*phone)(.*touch))|kindle|playbook|silk|(puffin(?!.*(IP|AP|WP))))/.test(userAgent);
}

/**
 * 배열을 랜덤하게 뒤 섞는 함수
 * @async
 * @returns {array}
 */
function shuffle(array) {
  var currentIndex = array.length,
    temporaryValue,
    randomIndex;

  while (0 !== currentIndex) {
    randomIndex = Math.floor(Math.random() * currentIndex);
    currentIndex -= 1;

    temporaryValue = array[currentIndex];
    array[currentIndex] = array[randomIndex];
    array[randomIndex] = temporaryValue;
  }

  return array;
}
/**
 * 로딩 화면 출력
 */
const maxTimeout = 30000;
function startLoading(timeout) {
  var timeout = timeout || 100000;
  if (timeout === 0) timeout = maxTimeout;
  secukit.config.jqueryAlias('.secukit-loading').removeClass('secukit-d-none');
  // 로딩 화면 타임아웃 (10초)
  setTimeout(() => {
    secukit.config.jqueryAlias('.secukit-loading').addClass('secukit-d-none');
  }, timeout);
}
/**
 * 로딩 화면 내리기
 */
function stopLoading() {
  secukit.config.jqueryAlias('.secukit-loading').addClass('secukit-d-none');
}

