import { call } from './communicator';
import log from '../../../common/logger';

export default {
  initCert: function () {
    return call('initCert', { certID: secukit.context.cert.nxs.certID });
  },
  initCertIssue: function () {
    return call('initCertIssue', { certID: secukit.context.cert.nxs.certID });
  },
  isLoadedCert: function () {
    return call('isLoadedCert', { certID: secukit.context.cert.nxs.certID });
  },
  GetVersion: function () {
    return call('GetVersion', { TOKEN: 'Getversion' });
  },
  checkLicense: function () {
    return call('checkLicense', {
      license: secukit.config.cert.nxs.license,
    });
  },
  setEnvironment: function () {
    return call('setEnvironment', {
      inCharset: secukit.config.charset !== 'utf8' ? 'UTF-8' : 'EUC-KR',
      outCharset: secukit.config.charset === 'utf8' ? 'UTF-8' : 'EUC-KR',
      nxLocale: secukit.config.lang === 'ko' ? 'KR' : 'EN',
    });
  },
  setCommonInfo: function () {
    return call('setCommonInfo', {
      caIP: secukit.config.cert.caIP,
      caCmpPort: secukit.config.cert.caCmpPort,
      anyPolicy: secukit.config.cert.allowedPolicyOIDs.length === 0 ? 'Y' : 'N',
      policies: secukit.config.cert.allowedPolicyOIDs.join('|'),
    });
  },
  setCommonInfoIssue: function () {
    return call('setCommonInfoIssue', {
      caIP: secukit.config.cert.caIP,
      caCmpPort: secukit.config.cert.caCmpPort,
      anyPolicy: secukit.config.cert.allowedPolicyOIDs.length === 0 ? 'Y' : 'N',
      policies: secukit.config.cert.allowedPolicyOIDs.join('|'),
    });
  },
  setIntegration: function (type) {
    return call('setIntegration', {
      type: type,
      param1: arguments[1],
      param2: arguments[2],
      param3: arguments[3],
      param4: arguments[4],
      param5: arguments[5],
      param6: arguments[6],
      param7: arguments[7],
      param8: arguments[8],
      param9: arguments[9],
      param10: arguments[10],
    });
  },
  setIntegrationIssue: function (type) {
    return call('setIntegrationIssue', {
      type: type,
      param1: arguments[1],
      param2: arguments[2],
      param3: arguments[3],
      param4: arguments[4],
      param5: arguments[5],
      param6: arguments[6],
      param7: arguments[7],
      param8: arguments[8],
      param9: arguments[9],
      param10: arguments[10],
    });
  },
  selectStorage: function (mediaType, extraValue) {
    if (mediaType === 'USB' || mediaType === 'HDD')
      this.selectStorageIssue(mediaType, extraValue).catch((e) => {
        log.error(e);
      });
    return this.setCommonInfo().then(() => {
      return call('selectStorage', { mediaType: mediaType, extraValue: extraValue || 'NULL' });
    });
  },
  selectStorageIssue: function (mediaType, extraValue) {
    return this.setCommonInfoIssue().then(() => {
      return call('selectStorageIssue', { mediaType: mediaType, extraValue: extraValue || 'NULL' });
    });
  },
  selectCertificate: function (id, password) {
    return call('selectCertificate', { ID: id, password: password, certID: secukit.context.cert.nxs.certID });
  },
  selectCertificateIssue: function (id, password) {
    return call('selectCertificateIssue', { ID: id, password: password, certID: secukit.context.cert.nxs.certID });
  },
  viewCertDetailInfomation: function (id) {
    return call('viewCertDetailInfomation', { ID: id });
  },
  getFilePath: function (fileType) {
    return call('getFilePath', { fileType: fileType });
  },
  getPrimaryHardwareInfo: function (fileType) {
    return call('getPrimaryHardwareInfo', {});
  },
  getHsmDeviceInformation: function (deviceName) {
    return call('getHsmDeviceInformation', { deviceName: deviceName });
  },
  getBioHsmDeviceInformation: function (extraValue, publicNumber) {
    return call('getBioHsmDeviceInformation', { extraValue: extraValue, extraValue2: publicNumber, certID: secukit.context.cert.nxs.certID });
  },
  importP12: function (filePath, fileName, password) {
    return call('importP12', { filePath: filePath, fileName: fileName, password: password, certID: '' });
  },
  importP12FromData: function (p12, password, mediaType, extraValue) {
    return call('importP12FromData', {
      data: p12,
      password: password,
      mediaType: mediaType,
      extraValue: extraValue,
      certID: '',
    });
  },
  exportP12: function (fileName, certID) {
    return call('exportP12', { certType: 'EncryptCert', filePath: '', fileName: fileName, certID: certID });
  },
  exportP12ToData: function () {
    return call('exportP12ToData', { certType: 'EncryptCert', certID: secukit.context.cert.nxs.certID });
  },
  viewCertInfomationWithVID: function () {
    return call('viewCertInfomationWithVID', {
      certType: 'SignCert',
      certID: secukit.context.cert.nxs.certID,
      isViewVID: "1"
    });
  },
  viewCertInfomationWithVIDIssue: function () {
    return call('viewCertInfomationWithVIDIssue', {
      certType: 'SignCert',
      certID: secukit.context.cert.nxs.certID,
      isViewVID: "1"
    });
  },
  generateSignatureData: function (message, algorithm) {
    return call('generateSignatureData', {
      certType: 'SignCert',
      sourceString: message,
      algorithm: algorithm,
      certID: secukit.context.cert.nxs.certID,
    });
  },
  generateSignatureFile: function (inFilePath, outFilePath, algorithm) {
    return call('generateSignatureFile', {
      certType: 'SignCert',
      sourceFilePath: inFilePath,
      outFileName: outFilePath,
      algorithm: algorithm,
      certID: secukit.context.cert.nxs.certID,
      beString: 'false',
    });
  },
  verifySignatureData: function (signature, message, algorithm) {
    return call('verifySignatureData', {
      certType: 'SignCert',
      signatureString: signature,
      sourceString: message,
      algorithm: algorithm,
      certID: secukit.context.cert.nxs.certID,
    });
  },
  verifySignatureFile: function (signatureFilePath, inFilePath, algorithm) {
    return call('verifySignatureFile', {
      certType: 'SignCert',
      signatureFilePath: signatureFilePath,
      sourceFilePath: inFilePath,
      algorithm: algorithm,
      certID: secukit.context.cert.nxs.certID,
    });
  },
  genUCPIDRequestInfo: function (userAgreementMsg, isRealName, isGender, isNationalInfo, isBirthDate, isCI, ispUrlInfo) {
    return call('genUCPIDRequestInfo', {
      userAgreementMsg: userAgreementMsg,
      isRealName: isRealName,
      isGender: isGender,
      isNationalInfo: isNationalInfo,
      isBirthDate: isBirthDate,
      isCI: isCI,
      ispUrlInfo: ispUrlInfo,
      certID: secukit.context.cert.nxs.certID,
    });
  },
  generatePKCS7SignedData: function (message) {
    return call('generatePKCS7SignedData', {
      certType: 'SignCert',
      sourceString: message,
      certID: secukit.context.cert.nxs.certID,
    });
  },
  generatePKCS7SignedFile: function (inFilePath, outFilePath) {
    return call('generatePKCS7SignedFile', {
      certType: 'SignCert',
      sourceFilePath: inFilePath,
      outFileName: outFilePath,
      outFileType: '',
      certID: secukit.context.cert.nxs.certID,
    });
  },
  generatePKCS7SignedFileToData: function (inFilePath) {
    return call('generatePKCS7SignedFileToData', {
      certType: 'SignCert',
      sourceFilePath: inFilePath,
      certID: secukit.context.cert.nxs.certID,
    });
  },
  generatePKCS7EnvelopedData: function (message, targetCert) {
    return call('generatePKCS7EnvelopedData', { targetCert: targetCert, sourceString: message });
  },
  generatePKCS7EnvelopedFile: function (inFilePath, outFilePath, targetCert) {
    return call('generatePKCS7EnvelopedFile', { targetCert: targetCert, sourceFilePath: inFilePath, outFileName: outFilePath, outFileType: '' });
  },
  generatePKCS7EnvelopedFileToData: function (inFilePath, targetCert) {
    return call('generatePKCS7EnvelopedFileToData', { targetCert: targetCert, sourceFilePath: inFilePath });
  },
  generatePKCS7SignedAndEnvelopedData: function (message, targetCert) {
    return call('generatePKCS7SignedAndEnvelopedData', {
      certType: 'SignCert',
      kmServerCert: targetCert,
      cRandom: '',
      pText: message,
      certID: secukit.context.cert.nxs.certID,
    });
  },
  generatePKCS7SignedAndEnvelopedFile: function (inFilePath, outFilePath, targetCert) {
    return call('generatePKCS7SignedAndEnvelopedFile', {
      certType: 'SignCert',
      kmServerCert: targetCert,
      cRandom: '',
      sourceFilePath: inFilePath,
      outFileName: outFilePath,
      outFileType: '',
      certID: secukit.context.cert.nxs.certID,
    });
  },
  generatePKCS7SignedAndEnvelopedFileToData: function (inFilePath, targetCert) {
    return call('generatePKCS7SignedAndEnvelopedFileToData', {
      certType: 'SignCert',
      kmServerCert: targetCert,
      cRandom: '',
      sourceFilePath: inFilePath,
      certID: secukit.context.cert.nxs.certID,
    });
  },
  addPKCS7SignedData: function (signature) {
    return call('addPKCS7SignedData', {
      certType: 'SignCert',
      sourceString: signature,
      certID: secukit.context.cert.nxs.certID,
    });
  },
  addPKCS7SignedFile: function (inFilePath, outFilePath) {
    return call('addPKCS7SignedFile', {
      certType: 'SignCert',
      sourceFilePath: inFilePath,
      sourceFileType: '',
      outFileName: outFilePath,
      outFileType: '',
      certID: secukit.context.cert.nxs.certID,
    });
  },
  verifyPKCS7SignedData: function (signature) {
    return call('verifyPKCS7SignedData', { signedString: signature });
  },
  verifyPKCS7SignedFile: function (signatureFilePath, outFilePath) {
    return call('verifyPKCS7SignedFile', { signedFilePath: signatureFilePath, inFileType: '', outFileName: outFilePath });
  },
  verifyPKCS7EnvelopedData: function (envelopedMessage) {
    return call('verifyPKCS7EnvelopedData', { certType: 'SignCert', envelopedString: envelopedMessage, certID: secukit.context.cert.nxs.certID });
  },
  verifyPKCS7EnvelopedFile: function (inFilePath, outFilePath) {
    return call('verifyPKCS7EnvelopedFile', {
      certType: 'SignCert',
      envelopedFilePath: inFilePath,
      inFileType: '',
      outFileName: outFilePath,
      certID: secukit.context.cert.nxs.certID,
    });
  },
  extractCertificatesFromMultiPKCS7SignedData: function (signature, order) {
    return call('extractCertificatesFromMultiPKCS7SignedData', { order: order, signedString: signature });
  },
  extractCertificatesFromMultiPKCS7SignedFile: function (inFilePath, outFilePath, order) {
    return call('extractCertificatesFromMultiPKCS7SignedFile', {
      order: order,
      signedFilePath: inFilePath,
      signedFileType: '',
      outFileName: outFilePath,
    });
  },
  extractTimeValuesFromMultiPKCS7SignedData: function (signature, order) {
    return call('extractTimeValuesFromMultiPKCS7SignedData', { order: order, signedString: signature });
  },
  extractTimeValuesFromMultiPKCS7SignedFile: function (inFilePath, order) {
    return call('extractTimeValuesFromMultiPKCS7SignedFile', {
      order: order,
      signedFilePath: inFilePath,
      signedFileType: '',
    });
  },
  extractOriginalDataFromMultiPKCS7SignedData: function (signature) {
    return call('extractOriginalDataFromMultiPKCS7SignedData', { signedString: signature });
  },
  extractOriginalDataFromMultiPKCS7SignedFile: function (signatureFilePath, outFilePath) {
    return call('extractCertificatesFromMultiPKCS7SignedFile', {
      signedFilePath: signatureFilePath,
      signedFileType: '',
      outFileName: outFilePath,
    });
  },
  extractCertCountFromMultiPKCS7SignedData: function (signature) {
    return call('extractCertCountFromMultiPKCS7SignedData', { signedString: signature });
  },
  extractCertCountFromMultiPKCS7SignedFile: function (signatureFilePath) {
    return call('extractCertCountFromMultiPKCS7SignedFile', {
      signedFilePath: signatureFilePath,
      signedFileType: '',
    });
  },
  encodeBase64Data: function (message) {
    return call('encodeBase64Data', { sourceString: message });
  },
  encodeBase64File: function (inFilePath, outFilePath) {
    return call('encodeBase64File', { sourceFilePath: inFilePath, outFileName: outFilePath });
  },
  decodeBase64Data: function (base64Message) {
    return call('decodeBase64Data', { encodedBase64String: base64Message });
  },
  decodeBase64File: function (inFilePath, outFilePath) {
    return call('decodeBase64File', { encodedFilePath: inFilePath, outFileName: outFilePath });
  },
  generateHashValue: function (message, algorithm) {
    return call('generateHashValue', { digestAlg: algorithm, srcData: message });
  },
  generateHashFileToFile: function (inFilePath, outFilePath, algorithm) {
    return call('generateHashFileToFile', { digestAlg: algorithm, sourceFilePath: inFilePath, outFileName: outFilePath });
  },
  generateHashFileToString: function (inFilePath, algorithm) {
    return call('generateHashFileToString', { digestAlg: algorithm, sourceFilePath: inFilePath });
  },
  generateMAC: function (message, password, algorithm) {
    return call('generateHashValue', { digestAlg: algorithm, srcData: message, macKey: password });
  },
  generateMACFileToFile: function (inFilePath, outFilePath, password, algorithm) {
    return call('generateMACFileToFile', { digestAlg: algorithm, sourceFilePath: inFilePath, outFileName: outFilePath, macKey: password });
  },
  generateMACFileToString: function (inFilePath, password, algorithm) {
    return call('generateMACFileToString', { digestAlg: algorithm, sourceFilePath: inFilePath, macKey: password });
  },
  symmetricEncryptData: function (message, algorithm) {
    return call('symmetricEncryptData', { algorithm: algorithm, keyName: secukit.context.cert.nxs.keyName, sourceString: message });
  },
  symmetricEncryptFile: function (inFilePath, outFilePath, algorithm) {
    return call('symmetricEncryptFile', {
      algorithm: algorithm,
      keyName: secukit.context.cert.nxs.keyName,
      sourceFilePath: inFilePath,
      outFileName: outFilePath,
    });
  },
  symmetricDecryptData: function (encMessage) {
    return call('symmetricDecryptData', { keyName: secukit.context.cert.nxs.keyName, encryptedString: encMessage });
  },
  symmetricDecryptFile: function (inFilePath, outFilePath) {
    return call('symmetricDecryptFile', { keyName: secukit.context.cert.nxs.keyName, enctyptedFilePath: inFilePath, outFileName: outFilePath });
  },
  genSymmetricKey: function (IV, algorithm) {
    return call('genSymmetricKey', { algorithm: algorithm, IV: IV, keyName: secukit.context.cert.nxs.keyName });
  },
  getSymmetricKey: function (targetCert, rsaVersion) {
    return call('getSymmetricKey', { serverCert: targetCert, rsaVersion: rsaVersion, keyName: secukit.context.cert.nxs.keyName });
  },
  getSymmetricIV: function (targetCert, rsaVersion) {
    return call('getSymmetricIV', { serverCert: targetCert, rsaVersion: rsaVersion, keyName: secukit.context.cert.nxs.keyName });
  },
  getSymmetricKeyIV: function (targetCert, rsaVersion) {
    return call('getSymmetricKeyIV', { serverCert: targetCert, rsaVersion: rsaVersion, keyName: secukit.context.cert.nxs.keyName });
  },
  getSymmetricKeySelf: function (rsaVersion) {
    return call('getSymmetricKeySelf', {
      certType: 'SignCert',
      certID: secukit.context.cert.nxs.certID,
      rsaVersion: rsaVersion,
      keyName: secukit.context.cert.nxs.keyName,
    });
  },
  getSymmetricKeyIVSelf: function (rsaVersion) {
    return call('getSymmetricKeyIVSelf', {
      certType: 'SignCert',
      certID: secukit.context.cert.nxs.certID,
      rsaVersion: rsaVersion,
      keyName: secukit.context.cert.nxs.keyName,
    });
  },
  setSymmetricKeyIVSelf: function () {},
  clearSymmetricKey: function () {
    return call('clearSymmetricKey', { keyName: secukit.context.cert.nxs.keyName });
  },
  verifyVID: function (ssn) {
    return call('verifyVID', { ssn: ssn, certID: secukit.context.cert.nxs.certID });
  },
  getVIDRandomValue: function () {
    return call('getVIDRandomValue', { certID: secukit.context.cert.nxs.certID });
  },
  getPrikey: function (targetCert, rsaVersion) {
    return call('getPrikeyEx', {
      certType: 'SignCert',
      pkcsSpec: 'PKCS8',
      kmServerCert: targetCert,
      rsaVersion: rsaVersion,
      certID: secukit.context.cert.nxs.certID,
      messageType: 'p7e',
    });
  },
  getPrikeyEWS: function () {
    return call('getPrikeyEWS', {
      certType: 'SignCert',
      certID: secukit.context.cert.nxs.certID,
    });
  },
  getPrikeyWithNewPassword: function (password) {
    return call('getPrikeyWithNewPassword', {
      certType: 'SignCert',
      messageType: 'PEM',
      password: password,
      certID: secukit.context.cert.nxs.certID,
    });
  },
  rsaEncrypt: function (message, rsaVersion, targetCert) {
    return call('rsaEncrypt', { certString: targetCert, sourceString: message, rsaVersion: rsaVersion });
  },
  rsaDecrypt: function (encMessage, rsaVersion, certType) {
    return call('rsaDecrypt', { certType: certType, encData: encMessage, rsaVersion: rsaVersion, certID: secukit.context.cert.nxs.certID });
  },
  rsaDecryptToBase64: function (encMessage, rsaVersion, certType) {
    return call('rsaDecryptToBase64', { certType: certType, encData: encMessage, rsaVersion: rsaVersion, certID: secukit.context.cert.nxs.certID });
  },
  verifyKeyPair: function () {
    return call('verifyKeyPair', { certType: 'SignCert', certID: secukit.context.cert.nxs.certID });
  },
};